), classified AS (
  SELECT
    item_name,
    response_rows,
    populated_rows,
    distinct_values,
    min_value,
    max_value,
    CASE
      WHEN populated_rows = 0 THEN 'empty'
      WHEN distinct_values = 2 AND binary_01_rows = populated_rows THEN 'binary_0_1'
      WHEN distinct_values = 1 AND binary_01_rows = populated_rows THEN 'constant_0_or_1'
      WHEN within_1_5_rows = populated_rows AND distinct_values > 2 THEN 'ordinal_1_5_or_subset'
      WHEN within_1_5_rows = populated_rows THEN 'ordinal_1_5_subset'
      ELSE 'other_or_mixed'
    END AS observed_domain,
    binary_01_rows,
    within_1_5_rows,
    outside_1_5_rows,
    non_binary_rows
  FROM item_profile
)
