  item_name,
  response_rows,
  populated_rows,
  distinct_values,
  min_value,
  max_value,
  observed_domain,
  binary_01_rows,
  within_1_5_rows,
  outside_1_5_rows,
  non_binary_rows
FROM classified
ORDER BY item_name;
